messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Car Race 3D</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { overflow: hidden; background: #000; }
  canvas { display: block; width: 100vw; height: 100vh; }
</style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x87CEEB, 0.008);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 500);
camera.position.set(0, 25, 30);
camera.lookAt(0, 0, 150);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0x87CEEB, 0.6);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xFFFFEE, 1.2);
dirLight.position.set(80, 120, 60);
scene.add(dirLight);

const groundLight = new THREE.DirectionalLight(0x4488FF, 0.5);
groundLight.position.set(-60, 40, -20);
scene.add(groundLight);

// --- Ground ---
const groundGeo = new THREE.PlaneGeometry(400, 400, 64, 64);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.8, metalness: 0.1 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.1;
scene.add(ground);

// Road surface
const roadGeo = new THREE.PlaneGeometry(28, 300, 64, 64);
const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.5, metalness: 0.1 });
const road = new THREE.Mesh(roadGeo, roadMat);
road.rotation.x = -Math.PI / 2;
road.position.y = -0.1;
scene.add(road);

// Road center line
const centerGeo = new THREE.PlaneGeometry(1, 300, 1, 64);
const centerMat = new THREE.MeshBasicMaterial({ color: 0xFFFF00, transparent: true, opacity: 0.5 });
const centerLine = new THREE.Mesh(centerGeo, centerMat);
centerLine.rotation.x = -Math.PI / 2;
centerLine.position.y = -0.1;
scene.add(centerLine);

// Road edge lines
const edgeGeo = new THREE.PlaneGeometry(0.02, 300, 1, 64);
const edgeMat = new THREE.MeshBasicMaterial({ color: 0xFFFF00, transparent: true, opacity: 0.4 });
const edgeLeft = new THREE.Mesh(edgeGeo, edgeMat);
edgeLeft.rotation.x = -Math.PI / 2;
edgeLeft.position.set(-14, -0.1, 0);
scene.add(edgeLeft);
const edgeRight = new THREE.Mesh(edgeGeo, edgeMat);
edgeRight.rotation.x = -Math.PI / 2;
edgeRight.position.set(14, -0.1, 0);
scene.add(edgeRight);

// --- Finish line ---
const finishGeo = new THREE.PlaneGeometry(10, 4, 16, 16);
const finishMat = new THREE.MeshBasicMaterial({ color: 0xFFFF00, transparent: true, opacity: 0.7 });
const finishLine = new THREE.Mesh(finishGeo, finishMat);
finishLine.rotation.x = -Math.PI / 2;
finishLine.position.set(160, 0.5, 0);
scene.add(finishLine);

// Finish line posts
for (let i = -1; i <= 1; i += 2) {
  const postGeo = new THREE.BoxGeometry(0.1, 1.2, 0.1);
  const postMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
  const post = new THREE.Mesh(postGeo, postMat);
  post.position.set(i * 6, 0.6, 160);
  scene.add(post);
}

// --- Car Creation ---
function createCar(color, name) {
  const group = new THREE.Group();

  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
  const wheelMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a });
  const wheelPositions = [
    [-1.2, -0.3, -0.5], [1.2, -0.3, -0.5],
    [-1.2, -0.3, 0.5], [1.2, -0.3, 0.5],
    [-1.2, -0.3, 1.2], [1.2, -0.3, 1.2],
    [-1.2, -0.3, 1.9], [1.2, -0.3, 1.9],
  ];
  wheelPositions.forEach(p => {
    const wheel = new THREE.Mesh(wheelGeo, wheelMat);
    wheel.position.set(p[0], -0.2, p[2]);
    wheel.rotation.z = Math.PI / 2;
    group.add(wheel);
  });

  // Body
  const bodyGeo = new THREE.BoxGeometry(3.2, 1.6, 2.8);
  const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: 0.3, metalness: 0.7 });
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.position.y = 0.8;
  group.add(body);

  // Roof
  const roofGeo = new THREE.BoxGeometry(2.6, 0.5, 2.2);
  const roofMat = new THREE.MeshStandardMaterial({ color, roughness: 0.3, metalness: 0.7 });
  const roof = new THREE.Mesh(roofGeo, roofMat);
  roof.position.y = 1.2;
  group.add(roof);

  // Windshield
  const windshieldGeo = new THREE.BoxGeometry(1.6, 0.15, 0.8);
  const windshieldMat = new THREE.MeshBasicMaterial({ color: 0x88CCFF, transparent: true, opacity: 0.6 });
  const windshield = new THREE.Mesh(windshieldGeo, windshieldMat);
  windshield.position.set(0, 1.2, 0.8);
  group.add(windshield);

  // Rear window
  const rearWindowGeo = new THREE.BoxGeometry(1.4, 0.15, 0.6);
  const rearWindowMat = new THREE.MeshBasicMaterial({ color: 0x88CCFF, transparent: true, opacity: 0.6 });
  const rearWindow = new THREE.Mesh(rearWindowGeo, rearWindowMat);
  rearWindow.position.set(0, 1.2, -1.4);
  group.add(rearWindow);

  // Headlights
  const headlightGeo = new THREE.BoxGeometry(0.7, 0.3, 0.4);
  const headlightMat = new THREE.MeshStandardMaterial({ color: 0xFFFF88 });
  const headlightL = new THREE.Mesh(headlightGeo, headlightMat);
  headlightL.position.set(-1.7, 0.85, -1.5);
  group.add(headlightL);
  const headlightR = new THREE.Mesh(headlightGeo, headlightMat);
  headlightR.position.set(1.7, 0.85, -1.5);
  group.add(headlightR);

  // Taillights
  const taillightGeo = new THREE.BoxGeometry(0.7, 0.3, 0.4);
  const taillightMat = new THREE.MeshStandardMaterial({ color: 0xFF4444 });
  const taillightL = new THREE.Mesh(taillightGeo, taillightMat);
  taillightL.position.set(-1.7, 0.85, 1.7);
  group.add(taillightL);
  const taillightR = new THREE.Mesh(taillightGeo, taillightMat);
  taillightR.position.set(1.7, 0.85, 1.7);
  group.add(taillightR);

  // Spoiler
  const spoilerGeo = new THREE.BoxGeometry(1.8, 0.25, 0.8);
  const spoilerMat = new THREE.MeshStandardMaterial({ color, roughness: 0.3, metalness: 0.7 });
  const spoiler = new THREE.Mesh(spoilerGeo, spoilerMat);
  spoiler.position.set(0, 0.7, 1.9);
  group.add(spoiler);

  group.position.y = -0.1;
  return group;
}

const blueCar = createCar(0x0066FF, 'Blue');
blueCar.position.set(-80, 0, 0);

const redCar = createCar(0xFF1144, 'Red');
redCar.position.set(-90, 0, 0);

scene.add(blueCar);
scene.add(redCar);

// --- UI ---
const ui = document.createElement('div');
ui.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);color:#fff;font-family:Arial,sans-serif;text-align:center;z-index:10;pointer-events:none;';
document.body.appendChild(ui);

const speedDisplay = document.createElement('div');
speedDisplay.style.cssText = 'font-size:24px;font-weight:bold;margin-bottom:8px;';
ui.appendChild(speedDisplay);

const positionDisplay = document.createElement('div');
positionDisplay.style.cssText = 'font-size:18px;margin-bottom:6px;';
ui.appendChild(positionDisplay);

const messageDisplay = document.createElement('div');
messageDisplay.style.cssText = 'font-size:16px;margin-bottom:12px;';
ui.appendChild(messageDisplay);

const lapDisplay = document.createElement('div');
lapDisplay.style.cssText = 'font-size:14px;margin-top:4px;';
ui.appendChild(lapDisplay);

// --- Race State ---
let raceState = 'idle'; // idle, racing, finished
let lapCount = 0;
let lastTime = 0;
let redHasWon = false;

// --- Update UI ---
function updateUI() {
  const redPos = redCar.position.z;
  const bluePos = blueCar.position.z;
  const trackLength = 160;

  if (raceState === 'idle') {
    speedDisplay.textContent = 'Waiting...';
    positionDisplay.textContent = '';
    messageDisplay.textContent = 'Press ENTER to start';
    lapDisplay.textContent = '';
  } else {
    const redSpeed = (redPos - (-90)) / (Date.now() - lastTime) * 60;
    const blueSpeed = (bluePos - (-90)) / (Date.now() - lastTime) * 60;
    speedDisplay.textContent = `${Math.round(redSpeed)} km/h`;

    if (redPos > bluePos) {
      positionDisplay.textContent = '🏆 Red is leading!';
      positionDisplay.style.color = '#FF4444';
    } else {
      positionDisplay.textContent = '🏆 Blue is leading!';
      positionDisplay.style.color = '#4488FF';
    }

    lapCount = Math.floor((redPos - (-90)) / trackLength);
    lapDisplay.textContent = `Lap: ${lapCount + 1}`;

    if (redPos >= trackLength) {
      messageDisplay.textContent = '🎉 Red wins the race! 🎉';
      messageDisplay.style.color = '#FFD700';
      raceState = 'finished';
      redHasWon = true;
      lastTime = Date.now();
    }
  }
}

// --- Animation Loop ---
function animate() {
  requestAnimationFrame(animate);
  const now = Date.now();

  // --- Race Logic ---
  if (raceState === 'idle') {
    if (window.event?.key === 'Enter' || window.event?.key === ' ') {
      window.event.preventDefault();
      raceState = 'racing';
      lastTime = now;
      messageDisplay.textContent = 'GO!';
      messageDisplay.style.color = '#00FF00';
    }
    // Idle animation
    blueCar.rotation.y += 0.02;
    redCar.rotation.y += 0.03;
  } else if (raceState === 'racing') {
    const dt = (now - lastTime) / 1000;
    lastTime = now;

    // Blue car: steady speed with slight variation
    const blueSpeed = 45 + Math.sin(now * 0.003) * 10;
    blueCar.position.z += blueSpeed * dt;

    // Red car: starts slow, accelerates, then overtakes
    const redTime = (redCar.position.z - (-90)) / 30; // time since start
    let redSpeed;
    if (redTime < 1.5) {
      // Slow start
      redSpeed = 20 + redTime * 15;
    } else if (redTime < 3) {
      // Acceleration phase
      redSpeed = 35 + redTime * 30;
    } else {
      // Max speed
      redSpeed = 75 + Math.sin(now * 0.005) * 5;
    }
    redCar.position.z += redSpeed * dt;

    // Check if red has won
    if (redCar.position.z >= 160) {
      raceState = 'finished';
      redHasWon = true;
    }
  } else if (raceState === 'finished') {
    // Reset after a delay
    if (now - lastTime > 2500) {
      lapCount = 0;
      redHasWon = false;
      blueCar.position.z = -80;
      redCar.position.z = -90;
      raceState = 'idle';
      lastTime = now;
      messageDisplay.textContent = 'Press ENTER to start';
      messageDisplay.style.color = '#888';
    }
  }

  // --- Camera Follow ---
  const avgZ = (blueCar.position.z + redCar.position.z) / 2;
  const targetCamPos = { x: 0, y: 25, z: avgZ + 15 };
  camera.position.lerp(new THREE.Vector3(targetCamPos.x, targetCamPos.y, targetCamPos.z), 0.05);
  camera.lookAt(new THREE.Vector3(0, 0, avgZ + 15));

  // --- Rotation ---
  blueCar.rotation.y += 0.01;
  redCar.rotation.y += 0.02;

  // --- Update UI ---
  updateUI();

  // --- Render ---
  renderer.render(scene, camera);
}

animate();

// --- Resize Handler ---
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
